/* Credit : Mughal.Dev */
.tectonic-trigger {
  position: relative;
  cursor: crosshair;
  padding: 12px 24px;
  background: #0f1115;
  border: 1px solid var(--slate-edge);
  color: #64748b;
  font-size: 0.75rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  transition: all 0.3s ease;
  z-index: 10;
}

.tectonic-trigger:hover {
  border-color: #fff;
  color: #fff;
  box-shadow: 0 0 30px rgba(255, 255, 255, 0.05);
}

.slab-tooltip {
  position: absolute;
  bottom: 150%;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition:
    transform 0.4s cubic-bezier(0.19, 1, 0.22, 1),
    opacity 0.4s cubic-bezier(0.19, 1, 0.22, 1);
  white-space: nowrap;
}

.slab-stack {
  position: relative;
  filter: drop-shadow(0 15px 35px rgba(0, 0, 0, 0.8));
}

.slab-layer {
  position: absolute;
  inset: 0;
  background: #0f1115;
  border: 1px solid #333a45;
  transition: transform 0.4s cubic-bezier(0.19, 1, 0.22, 1);
}

.layer-bottom {
  transform: translate(8px, 8px);
  background: #080808;
  z-index: 1;
}

.layer-mid {
  transform: translate(4px, 4px);
  background: #141414;
  z-index: 2;
}

.layer-top {
  position: relative;
  z-index: 3;
  background: #1e2228;
  padding: 10px 18px;
  border: 1px solid var(--slate-edge);
  display: flex;
  align-items: center;
  gap: 12px;
  overflow: hidden;
}

.layer-top::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.03;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='://www.w3.org/2000/svg'%3ExternalIcon%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
}

.layer-top::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.2),
    transparent
  );
}

.mono-tag {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.65rem;
  color: #64748b;
  background: rgba(0, 0, 0, 0.3);
  padding: 2px 6px;
  border-left: 2px solid #64748b;
}

.slab-text {
  color: #e2e8f0;
  font-size: 0.85rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.tectonic-trigger:hover .slab-tooltip {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.tectonic-trigger:hover .layer-bottom {
  transform: translate(12px, 12px);
}

.tectonic-trigger:hover .layer-mid {
  transform: translate(6px, 6px);
}

.slab-arrow {
  position: absolute;
  bottom: -6px;
  left: 50%;
  width: 12px;
  height: 12px;
  background: #0f1115;
  border-right: 1px solid var(--slate-edge);
  border-bottom: 1px solid var(--slate-edge);
  transform: translateX(-50%) rotate(45deg);
  z-index: 0;
}
